export const ASK_USER_TOOL_NAME = "ask_user";

/**
 * Action discriminator generated by the SDK for the client-defined ask_user
 * tool (`ClientAction_<tool-name>`). Keep the SDK naming convention contained
 * here instead of repeating its generated class name.
 */
export const ASK_USER_ACTION_KIND = "AskUserAction" as const;

/**
 * Prefix of the message the frontend posts back once the user answers the
 * decision card. Client tools are acknowledged before the user acts, so
 * this message is the only way to tell the agent the chosen answer.
 * It is masked from the chat (see `should-render-event.ts`).
 */
export const ASK_USER_RESULT_PREFIX = "[ask-user] ";

export const ASK_USER_LEDGER_STORAGE_KEY_PREFIX =
  "openhands-ask-user-requests:";
